using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.TKT.ComentariosTicket;using GraphApi.Services.TKT.ComentariosTicket;namespace GraphApi.Controllers.TKT.ComentariosTicket{    /// <summary>    /// Gestión de ComentariosTickets: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("TKT/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre ComentariosTickets")]    public class ComentariosTicketController : Controller    {        private readonly IComentariosTicketService _objService;        public ComentariosTicketController(IComentariosTicketService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los ComentariosTickets, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="comentarioTicketID">ComentarioTicketID</param>        /// <param name="ticketID">TicketID</param>        /// <param name="usuarioID">UsuarioID</param>        /// <param name="comentario">Comentario</param>        /// <param name="fechaComentario">FechaComentario</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de ComentariosTickets</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar ComentariosTickets",            Description = "Devuelve ComentariosTickets aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadComentariosTicket>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadComentariosTicket>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? comentarioTicketID,            [FromQuery] int? ticketID,            [FromQuery] int? usuarioID,            [FromQuery] string? comentario,            [FromQuery] DateTime? fechaComentario,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetComentariosTicketsDynamic(                comentarioTicketID,                 ticketID,                 usuarioID,                 comentario,                 fechaComentario,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo ComentariosTicket.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del ComentariosTicket a crear.</param>        /// <returns>El ComentariosTicket recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear ComentariosTickets",            Description = "Inserta un nuevo ComentariosTicket en la base de datos."        )]        [ProducesResponseType(typeof(clReadComentariosTicket), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadComentariosTicket>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateComentariosTicket objInput)        {            var vCreated = await _objService.CreateComentariosTicket(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de ComentariosTicket.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del ComentariosTicket.</param>        /// <returns>El ComentariosTicket actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar ComentariosTickets",            Description = "Actualiza uno o varios campos de ComentariosTicket existente."        )]        [ProducesResponseType(typeof(clReadComentariosTicket), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadComentariosTicket>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateComentariosTicket objInput)        {            var vUpdated = await _objService.UpdateComentariosTicket(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un ComentariosTicket por su ID.        /// </summary>        [HttpDelete("{nComentariosTicketID:int}")]        [SwaggerOperation(            Summary = "Eliminar ComentariosTicket",            Description = "Borra un ComentariosTicket si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nComentariosTicketID)        {            var success = await _objService.DeleteComentariosTicket(nComentariosTicketID);            return success ? NoContent() : NotFound();        }    }}